<?php if($page==='biz-invoices'): $invoices=query('SELECT i.*,c.name,COALESCE((SELECT SUM(cents) FROM biz_payments WHERE invoice_id=i.id),0) paid FROM biz_invoices i JOIN biz_clients c ON c.id=i.client_id ORDER BY i.id DESC LIMIT 200')->fetchAll(); ?><section class="panel"><h2>인보이스 · 미수금</h2><table><thead><tr><th>인보이스</th><th>거래처</th><th>Total</th><th>잔액</th></tr></thead><tbody><?php foreach($invoices as $i): ?><tr><td><a href="/?page=biz-invoice&id=<?=$i['id']?>">RN<?=$i['id']?> · <?=e($i['issued'])?></a></td><td><?=e($i['name'])?></td><td><?=money($i['total_cents'])?></td><td><?=money($i['total_cents']-$i['paid'])?></td></tr><?php endforeach ?></tbody></table></section>
<?php else:$deliveries=query('SELECT d.*,c.name,c.code,p.category,p.ko,p.en,p.pack FROM biz_deliveries d JOIN biz_clients c ON c.id=d.client_id JOIN biz_products p ON p.id=d.product_id WHERE d.cancelled=0 ORDER BY d.day DESC,d.id DESC LIMIT 300')->fetchAll(); ?><section class="panel"><h2><?=$page==='biz-results'?'납품 후 실제 판매·반품':'생산 예정 · 납품 확인'?></h2><p>개별 제품의 실제 납품 수량을 확인합니다. 위탁 재고는 이전 납품분도 남은 수량까지 판매를 추가할 수 있습니다.</p><?php foreach($deliveries as $d):$available=$d['sent']?bizAvailable((int)$d['id']):0; ?><div class="biz-delivery"><strong><?=e($d['day'].' · '.$d['name'].' · '.bizLabel($d))?></strong><span><?=e($d['fulfillment']==='pickup'?'픽업':'납품·배달')?> · 계획 <?=$d['planned']?> · 납품 <?=$d['delivered']?> · 남은 재고 <?=$available?></span><?php if(!$d['sent']): ?><details class="biz-plan-edit"><summary>계획 수량 수정·취소</summary><form method="post" class="biz-inline"><?=csrf()?><input type="hidden" name="action" value="biz_plan_update"><input type="hidden" name="id" value="<?=$d['id']?>"><input type="hidden" name="version" value="<?=$d['version']?>"><label>예정 수량 (0은 취소)<input name="planned" type="number" min="0" max="10000" value="<?=$d['planned']?>" required></label><button class="button secondary">계획 수정</button></form></details><form method="post" class="biz-inline"><?=csrf()?><input type="hidden" name="action" value="biz_deliver"><input type="hidden" name="id" value="<?=$d['id']?>"><label>실제 납품<input name="delivered" type="number" min="1" max="10000" value="<?=$d['planned']?>" required></label><?php if(!$d['code']): ?><label>개인 할인 (%)<input name="discount" type="number" min="0" max="100" value="<?=$d['discount_bp']/100?>" step=".01"></label><?php endif ?><button class="button">납품 완료</button></form><?php elseif(bizConsigned((string)$d['code'],$d['category'])): ?><form method="post" class="biz-inline"><?=csrf()?><input type="hidden" name="action" value="biz_result"><input type="hidden" name="id" value="<?=$d['id']?>"><input type="hidden" name="request_key" value="<?=bin2hex(random_bytes(16))?>"><label>판매일<input name="day" type="date" min="<?=$d['day']?>" value="<?=$today?>" required></label><label>판매 수량<input name="sold" type="number" min="0" max="<?=$available?>" value="0" required></label><label>반품·폐기<input name="returned" type="number" min="0" max="<?=$available?>" value="0"></label><button class="button">마감 기록</button></form><?php elseif($d['code']==='PT'): ?><span class="badge">월 정산 대기 · Staff Purchases는 인보이스에서 입력</span><?php else: ?><span class="badge done">직매출 기록 완료</span><?php endif ?></div><?php endforeach ?></section><?php endif ?>
